{
  "meta": {
    "title": "Seedance 2.0 电影级视觉执导系统",
    "version": "Protocol 5.6 极致光影版",
    "description": "AI生成视频分镜的核心指导协议，所有输出必须严格遵循此标准"
  },
  "part1": {
    "name": "技术标准 (Technical Standards)",
    "sections": {
      "1.1": {
        "title": "画幅与构图",
        "content": {
          "画幅": "竖屏 9:16",
          "核心调度轴": "Z轴（纵深）调度"
        },
        "foreground_framing": {
          "description": "前景遮挡 (Foreground Framing)：利用前景元素增加画面层次感",
          "rules": [
            "前景道具大光圈虚化处理",
            "前景占比建议5-15%画幅",
            "前景可作为框架引导视线聚焦主体"
          ],
          "examples": [
            "不锈钢门框边缘作为前景虚化",
            "实验室仪器轮廓作为前景遮挡",
            "人物肩袖/发丝作为前景虚化"
          ]
        }
      },
      "1.2": {
        "title": "影调 (Tone)",
        "content": [
          "高级灰 (Premium Gray Tone)",
          "无曝光过度",
          "无死黑（暗部保留纹理细节）",
          "8K 超清细节",
          "RED 专业摄影机质感",
          "色彩深度增强",
          "85mm 长焦空间压缩",
          "大光圈极浅景深",
          "柯达500T电影胶片 (Kodak 500T Vision3)",
          "变形宽荧幕镜头 (Anamorphic Lens)",
          "胶片颗粒消除数码感",
          "变形镜头椭圆焦外光斑",
          "45°侧光 (45° Side Lighting)",
          "面部柔光增强电影质感 (Facial Soft Light for Cinematic Texture)"
        ]
      },
      "1.3": {
        "title": "物理标准 (Physics)",
        "table": {
          "header": ["类型", "要求"],
          "rows": [
            ["极浅景深 (Shallow DoF)", "大光圈，虚化背景，锁死主体皮肤、瞳孔，毛发等8K纹理细节"],
            ["手持微动 (Organic Tremor)", "模拟呼吸感与步伐震颤，还原真实拍摄环境"],
            ["听觉 (Soundscape)", "严禁BGM，仅保留物理音效（靴子砂砾摩擦、沉重呼吸、器物碰撞声）"]
          ]
        }
      },
      "1.4": {
        "title": "角色形象标准 (Character Identity)",
        "table": {
          "header": ["要求", "说明"],
          "rows": [
            ["五官特征", "根据图片输入推理角色五官特征，不做任何自由发挥"],
            ["一致性", "多镜头的同一角色必须保持形象高度统一"]
          ]
        },
        "core_principle": "严禁凭空捏造角色外观。一切形象依据必须来源于图片输入推理。"
      },
      "1.5": {
        "title": "禁止项",
        "content": [
          "不允许出现字幕、文字等信息",
          "不允许凭空构思空间"
        ]
      },
      "1.6": {
        "title": "布光标准 (Lighting Standards)",
        "description": "强制要求以下布光规范以确保电影级视觉质感：",
        "table": {
          "header": ["布光类型", "说明"],
          "rows": [
            ["侧光 (Side Lighting)", "强制使用侧光增强角色轮廓，分离主体与背景"],
            ["三点布光法 (Three-point Lighting)", "主对话场景必须遵循：主光(Key Light)+补光(Fill Light)+轮廓光(Rim Light)"],
            ["主光 (Key Light)", "45度侧上方打光，塑造面部立体感"],
            ["补光 (Fill Light)", "对侧柔和补光，填充主光造成的阴影"],
            ["轮廓光 (Rim Light)", "从后方勾勒角色轮廓，增强与背景的分离感"]
          ]
        },
        "emphasis": {
          "面部轮廓阴影": "强调角色面部轮廓阴影，增加纵深层次",
          "8K皮肤纹理": "8K级别皮肤纹理细节，暗部必须保留毛孔，毛发等细节",
          "45度侧光": "强制使用45°侧光塑造立体轮廓，增强面部明暗对比",
          "面部柔光": "必须配合面部柔光处理，增强电影级皮肤质感，避免生硬高光"
        },
        "rules": [
          "主对话场景必须使用三点布光法",
          "强制使用45°侧光塑造立体轮廓，同时必须配合面部柔光处理",
          "增强电影级的皮肤质感，避免生硬高光",
          "暗部必须保留纹理细节，避免死黑",
          "85mm长焦镜头需强化轮廓光以对抗空间压缩带来的平面感"
        ]
      },
      "1.7": {
        "title": "致命违禁词红线 (Fatal Errors - Absolute Blacklist)",
        "description": "⚠️ 绝对铁律：以下词汇为最高级别禁用，AI 输出中严禁出现，违者视为致命错误⚠️",
        "declaration": "【警告】以下词汇在任何情况下均不得出现于输出中，违者直接判定为不合格输出",
        "blacklist": {
          "gaze_forbidden": {
            "title": "视线违禁词（绝对禁止）",
            "terms": [
              "看向前方",
              "视线锁定前方",
              "看前面"
            ],
            "requirement": "必须写明具体人脸坐标或屏幕方位（如：视线看向 Center-Left、视线看向玛吉面部）",
            "wrong_examples": [
              "塞蕾娜看向前方",
              "玛吉视线锁定前方",
              "卢卡斯看前面"
            ]
          },
          "lighting_forbidden": {
            "title": "布光违禁词（绝对禁止）",
            "terms": [
              "眼神光",
              "强化眼神光"
            ],
            "requirement": "禁止画蛇添足的光影描述，布光标准已由1.6规范，无需额外添加眼神光描述",
            "wrong_examples": [
              "眼神光点缀瞳孔",
              "强化眼神光增加神采"
            ]
          },
          "duration_forbidden": {
            "title": "时长违禁数值（绝对禁止）",
            "terms": [
              "6s",
              "5.5s",
              "5.2s",
              "5.1s",
              "6秒",
              "5.5秒",
              "5.2秒"
            ],
            "requirement": "单镜头时长严禁超过5.0秒，任何大于5.0s的数值均为致命违禁",
            "correct_range": "合法时长范围：0.5s - 5.0s"
          }
        },
        "penalty_rule": "违禁词一旦出现，视为Prompt工程严重失误，输出结果不予采信"
      }
    }
  },
  "part2": {
    "name": "空间映射规则 (Spatial Mapping)",
    "sections": {
      "2.1": {
        "title": "坐标系统",
        "description": "根据图片输入推理空间关系，确定角色在屏幕上的精确坐标：",
        "gaze_direction": {
          "description": "视线方向 (Gaze Direction)：强制描述角色视线看向屏幕的哪个方位",
          "rules": [
            "必须使用「视线看向 [屏幕坐标/方位]」描述",
            "禁止使用：看向前方、看向远处、看向别处 等模糊描述",
            "视线方向应结合坐标系统：Center, L 1/3, R 2/3, Bottom-FG, Top-Middle, 画外 等",
            "在正反打中，A的视线方向必须与B的位置坐标在逻辑上完全互补"
          ],
          "examples": {
            "correct": [
              "塞蕾娜视线看向 Center-Left",
              "塞蕾娜视线看向画外 Right-Back",
              "塞蕾娜视线看向 Bottom-FG",
              "玛吉视线看向 Top-Middle"
            ],
            "wrong": [
              "塞蕾娜看向前方",
              "塞蕾娜看向玛吉",
              "玛吉看向别处"
            ]
          }
        },
        "proximity": {
          "description": "物理间距 (Proximity)：必须标注角色间距离",
          "rules": [
            "必须标注角色间精确距离（如：玛吉位于塞蕾娜右方1.5米处）",
            "即使背景角色也要描述与主角的精确距离",
            "防止角色站位过散，确保空间逻辑连贯",
            "85mm长焦压缩下，物理间距会被视觉压缩，但仍需标注实际距离"
          ]
        },
        "foreground_props": {
          "description": "前景道具 (Foreground Props)：根据场景推理合理道具并进行大光圈虚化处理",
          "rules": [
            "根据场景推理合理的前景道具",
            "前景道具必须进行大光圈虚化处理",
            "前景道具可作为视觉框架引导视线"
          ],
          "examples": [
            "实验室场景：显微镜边缘、试管架、不锈钢门框",
            "室内场景：家具边角、窗帘、门框",
            "户外场景：树枝、建筑边缘、栏杆"
          ]
        },
        "spacing_rule": "必须标注角色间距离，如「马库斯位于路西恩后侧0.5米处」，防止角色站位过散",
        "table": {
          "header": ["位置标签", "含义"],
          "rows": [
            ["Center", "画面中心"],
            ["L 1/3", "左三分之一"],
            ["R 2/3", "右三分之二"],
            ["Bottom-FG", "前景底部"],
            ["Bottom-Left", "左下区域"],
            ["Bottom-Center", "中下区域"],
            ["Right-Back", "右后方"],
            ["Left Edge", "左侧边缘"],
            ["Top-Middle", "顶部中心"],
            ["画外", "画框以外的空间"]
          ]
        }
      },
      "2.2": {
        "title": "身体朝向 (Orientation)",
        "table": {
          "header": ["标签", "含义"],
          "rows": [
            ["Profile", "正侧"],
            ["Full Frontal", "全正面"],
            ["3/4 Left / 3/4 Right", "斜侧"],
            ["Away", "背对"],
            ["Downward", "俯视"]
          ]
        }
      },
      "2.3": {
        "title": "背景地标 (Landmarks)",
        "description": "每一镜必须描述角色所在镜头中背景的简单描述，确保剪辑时的逻辑连贯。"
      }
    }
  },
  "part3": {
    "name": "分镜执行架构 (Execution Logic)",
    "sections": {
      "3.1": {
        "title": "空间建立原则",
        "description": "新场景或冲突升级点必须先使用 1-2秒全景 (LS) 确立人物关系。"
      },
      "3.2": {
        "title": "正反打体系 (Shot/Reverse Shot)",
        "vertical_telephoto_rule": {
          "title": "竖屏对话长焦法则 (Vertical Portrait Telephoto Rule)",
          "description": "针对9:16竖屏特性，强制要求在对话正反打(SRS)中遵循以下规则：",
          "primary_focal_length": "85mm：对话正反打首选焦段，利用长焦空间压缩感将角色间物理距离压缩，在画面中产生强烈对抗感",
          "dominant_shots": "MCU (中近景) 或 MS (中景)：作为对话主导景别",
          "compression_effect": "85mm长焦的空间压缩会使角色在画面中显得更近，角色间实际距离虽存在，但视觉上产生紧逼感",
          "no_two_shot_rule": {
            "title": "【最高禁令】严禁两人完整同框 (No Two-Shot)",
            "description": "非特殊情况，严禁两人完整同框。由于9:16画幅限制，若需交代站位关系，只允许使用过肩镜头露出另一人的局部身体（如肩膀、手臂），绝对禁止两人并排完整站立在画面中。",
            "rationale": "9:16竖屏画幅狭窄，两人完整同框会导致构图涣散、主体模糊、情绪张力瓦解。",
            "exception": "仅在极罕见的情绪高潮点（如和解、诀别等）方可例外处理"
          },
          "rules": [
            "对话正反打首选85mm焦段",
            "景别固定为MCU或MS",
            "利用85mm空间压缩感增强角色间对抗张力",
            "严禁使用广角(35mm以下)进行对话正反打",
            "【最高禁令】非特殊情况严禁两人完整同框（No Two-Shot）"
          ]
        },
        "clearing_rule": {
          "title": "清场法则 (Clearing Rule) - 第三人绝对清场",
          "description": "双人对话正反打（SRS）过程中的硬性规则",
          "strict_enforcement": {
            "title": "【绝对铁律强化版】内正反打/外正反打第三人清场规则",
            "description": "当镜头类型为【内正打】【外正打】【过肩正打】【过肩反打】且景别为 MCU/CU 时：",
            "hard_rules": [
              "画面中绝对只能出现对话的两人",
              "必须强制第三人完全出画（Out of Frame），不得残留任何身体部位",
              "严禁保留第三人的半身、轮廓或任何程度的虚化身影",
              "即便第三人在场景中真实存在，也必须通过走位或焦外处理使其完全消失"
            ],
            "rationale": "MCU/CU景别下，85mm长焦空间压缩已极度紧密，任何第三人的存在都会在视觉边缘产生干扰，破坏两人对抗的主体情绪。",
            "violation_penalty": "违反绝对清场规则将导致画面重心偏移，观众注意力被分散，两人对抗的张力营造彻底失效"
          },
          "rules": [
            "双人对话正反打过程中，强制将第三人移出画面（出画）",
            "或将其置于完全虚化的焦外空间",
            "严禁第三人在两人对抗的心理空间内产生视觉干扰"
          ],
          "warning": "违反清场法则将导致画面重心混乱，破坏两人对抗的张力营造"
        },
        "table": {
          "header": ["类型", "说明"],
          "rows": [
            ["情绪咬合", "景别随台词力度从松变紧：MS → MCU → CU → ECU"],
            ["内正反打", "过肩镜头 (OTS)，85mm首选"],
            ["外正反打", "单人镜头 (Single)，85mm首选"]
          ]
        },
        "shot_allocation": {
          "description": "镜头分配原则",
          "rules": [
            "A说话时，可切B的反应镜头；B说话时，可切A的反应镜头",
            "A的内心戏，可切B的反应镜头",
            "以情绪张力为驱动，而非机械对应说话者",
            "反应镜头可早于或晚于台词1-2帧入场，增强戏剧节奏"
          ]
        },
        "shot_matrix": {
          "description": "正反打矩阵：人物对话时，强制切入正反打稳定套路",
          "types": [
            "过肩外正打 (OTS Outer Front, 85mm) - 频率最高，对话基调",
            "过肩外反打 (OTS Outer Reverse, 85mm)",
            "内正打 (Inner Front / Clean Single, 85mm)",
            "内反打 (Inner Reverse / Clean Single, 85mm)",
            "侧身正打 (Profile Front, 85mm)",
            "侧身反打 (Profile Reverse, 85mm)",
            "骑轴正打 (On-axis Front, 85mm) - 视线直逼镜头，极具压迫感",
            "骑轴反打 (On-axis Reverse, 85mm) - 频率最低，仅用于情绪高潮"
          ],
          "reaction_shot_rule": "给予听者反应镜头来填补15秒空间，反应镜头时长约1-3秒",
          "priority_rules": [
            "竖屏对话首选85mm长焦正反打",
            "多用中景过肩镜头 (MS/MCU Over-the-shoulder)",
            "多用正反打体系",
            "以过肩镜头作为对话主导景别",
            "频次递减法则：对话戏必须以【过肩外正/反打】为最大基底（约占50%以上），为了避免视觉疲劳，需按上述1-8的顺序依次降低频率来穿插使用其他机位",
            "情绪匹配法则：常规对话用过肩，专注独白切内正反，展现疏离切侧身，情绪极致爆发或极度私密瞬间才使用骑轴镜头"
          ],
          "degree_rule": "30度法则：每切换一次镜头，水平角度需偏移约30度，严禁轴对称拍摄",
          "tightening_rule": "景别阶梯收紧：随着对话深入，焦段锁定在85mm区间内逐步收紧（MCU→CU→ECU），以表现情绪升温"
        }
      },
      "3.2.1": {
        "title": "Z轴调度强化 (Z-axis Scheduling)",
        "description": "利用角色在Z轴（纵深）的移动与前景道具形成位差：",
        "rules": [
          "前景道具大光圈虚化，与主体形成前中后景层次",
          "角色在Z轴上的前后移动可创造视觉空间深度",
          "85mm长焦配合Z轴调度可增强空间压缩感",
          "前景虚化可作为视觉框架引导观众视线聚焦主体"
        ],
        "foreground_blur_effect": "前景虚化可产生位差感，增强空间层次"
      },
      "3.3": {
        "title": "景别定义",
        "composition_ratio_principle": {
          "title": "【景别比重原则】",
          "description": "整个视频的镜头组成必须以中近景 (MCU)、特写 (CU)、大特写 (ECU) 为绝对核心主力。远景 (LS) 和全景 (MS) 仅作为开场或空间交代的短暂补充镜头，严禁滥用。",
          "core_shots": "MCU / CU / ECU：占据整体镜头数量的 80% 以上",
          "supplemental_shots": "LS / MS：仅作为转场和点缀使用，严禁将其作为叙事主体镜头",
          "rationale": "竖屏9:16画幅空间狭窄，远景和全景会稀释主体存在感，破坏情绪聚焦。唯有通过中近景与特写的密集切换，才能最大化利用竖屏的空间压缩优势。"
        },
        "table": {
          "header": ["缩写", "名称", "画面占比", "说明"],
          "rows": [
            ["LS", "远景", "人物占屏幕约20%", "仅作转场与点缀，严禁作为叙事主体"],
            ["MS", "全景", "人物全身占屏幕约50%", "仅作转场与点缀，严禁作为叙事主体"],
            ["MCU", "中近景", "腰部以上", "人物上半身，85mm竖屏对话主导景别"],
            ["CU", "特写", "脖子以上", "强调面部表情，85mm空间压缩"],
            ["ECU", "大特写", "局部特写", "手部、眼睛、嘴唇等身体局部"]
          ]
        }
      },
      "3.4": {
        "title": "动作匹配 (Action Match)",
        "description": "标注动作的"起势 (Start)"与"落势 (End)"，确保动作在不同景别间丝滑衔接。"
      },
      "3.5": {
        "title": "时长匹配",
        "table": {
          "header": ["参数", "数值"],
          "rows": [
            ["标准语速", "约200词/分钟（英文）"],
            ["每词时长", "约0.3秒/词"]
          ]
